import{_ as a,o as e,c as d,a2 as l}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"ローカルツール一覧","description":"Ollama、LM Studio、KoboldCPP、llama.cpp、LocalAI、Jan、text-generation-webui の比較；MiniTavern 向けローカル OpenAI 互換ツール選び。","frontmatter":{"title":"ローカルツール一覧","description":"Ollama、LM Studio、KoboldCPP、llama.cpp、LocalAI、Jan、text-generation-webui の比較；MiniTavern 向けローカル OpenAI 互換ツール選び。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"ローカルツール一覧 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Ollama、LM Studio、KoboldCPP、llama.cpp、LocalAI、Jan、text-generation-webui の比較；MiniTavern 向けローカル OpenAI 互換ツール選び。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/local/tools"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/local/tools"}]]},"headers":[],"relativePath":"ja/local/tools.md","filePath":"ja/local/tools.md","lastUpdated":1787224147000}'),o={name:"ja/local/tools.md"};function r(i,t,n,s,c,p){return e(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="ツール一覧" tabindex="-1">ツール一覧 <a class="header-anchor" href="#ツール一覧" aria-label="Permalink to &quot;ツール一覧&quot;">​</a></h1><p>MiniTavern は相手が <strong>OpenAI 互換</strong> の Chat Completions（またはそのプロトコルへ写像可能）を提供すれば、「カスタム」モデル接続で入れます。下表でツールを選んでください。</p><h2 id="比較" tabindex="-1">比較 <a class="header-anchor" href="#比較" aria-label="Permalink to &quot;比較&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ツール</th><th>難度</th><th>UI</th><th>モデル取得</th><th>ロールプレイ向け</th><th>典型 Base URL</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ja/ollama/install">Ollama</a></td><td>★☆☆</td><td>トレイ＋CLI</td><td><code>ollama pull</code></td><td>汎用対話が強い</td><td><code>http://IP:11434/v1</code></td></tr><tr><td><a href="/ultra_guides/ja/lmstudio/install">LM Studio</a></td><td>★☆☆</td><td>フル GUI</td><td>アプリ内ダウンロード</td><td>汎用</td><td><code>http://IP:1234/v1</code></td></tr><tr><td><a href="/ultra_guides/ja/koboldcpp/install">KoboldCPP</a></td><td>★★☆</td><td>軽量 GUI/CLI</td><td>自前 GGUF</td><td><strong>RP コミュニティで定番</strong></td><td><code>http://IP:5001/v1</code></td></tr><tr><td><a href="/ultra_guides/ja/llamacpp/install">llama.cpp server</a></td><td>★★★</td><td>CLI</td><td>自前 GGUF</td><td>制御しやすく軽い</td><td><code>http://IP:8080/v1</code></td></tr><tr><td><a href="/ultra_guides/ja/localai/install">LocalAI</a></td><td>★★☆</td><td>API／任意 UI</td><td>YAML／イメージ</td><td>多バックエンド</td><td><code>http://IP:8080/v1</code></td></tr><tr><td><a href="/ultra_guides/ja/jan/install">Jan</a></td><td>★☆☆</td><td>デスクトップ App</td><td>アプリ内</td><td>汎用</td><td>アプリ「API」ページ参照</td></tr><tr><td><a href="/ultra_guides/ja/textgen/install">text-generation-webui</a></td><td>★★★</td><td>Web UI</td><td>拡張が多い</td><td>プラグイン生態</td><td>OpenAI 拡張有効後</td></tr></tbody></table><h2 id="選び方-一言" tabindex="-1">選び方（一言） <a class="header-anchor" href="#選び方-一言" aria-label="Permalink to &quot;選び方（一言）&quot;">​</a></h2><ol><li><strong>最速で通したい</strong>：Ollama または LM Studio → <a href="/ultra_guides/ja/quickstart">30 分クイックスタート</a></li><li><strong>ロールプレイのプリセット／サンプラー重視</strong>：KoboldCPP</li><li><strong>GGUF があり、依存を最小に</strong>：llama.cpp <code>llama-server</code></li><li><strong>Docker／統一互換層</strong>：LocalAI</li><li><strong>一体型デスクトップ助手</strong>：Jan</li><li><strong>すでに oobabooga 環境</strong>：OpenAI 互換拡張を有効にして MiniTavern へ</li></ol><h2 id="共通の要件" tabindex="-1">共通の要件 <a class="header-anchor" href="#共通の要件" aria-label="Permalink to &quot;共通の要件&quot;">​</a></h2><p>どれを選んでも：</p><ol><li>サービスは <strong>LAN</strong> をリスン（<code>0.0.0.0</code> または「LAN デバイスを許可」）、<code>127.0.0.1</code> だけにしない</li><li>ファイアウォールで対応ポートを開放</li><li>スマホには <strong>PC の LAN IP</strong>、Base URL に <code>/v1</code>（ツール文書に別記がある場合を除く）</li><li>モデル名はツール表示の <strong>id／名称と完全一致</strong></li></ol><p>次：<a href="./models">推奨モデル</a> · <a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern での設定</a></p>',10)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
